import { defineConfig } from 'vite';
import { resolve } from 'path';
import { fileURLToPath } from 'url';
import mdBlogsPlugin from './vite-plugin-md-blogs.mjs';

const __dirname = fileURLToPath(new URL('.', import.meta.url));

export default defineConfig({
  base: '/',
  publicDir: 'static',
  plugins: [
    mdBlogsPlugin(),
  ],
  build: {
    rollupOptions: {
      input: {
        main:  resolve(__dirname, 'index.html'),
        blogs: resolve(__dirname, 'blogs/index.html'),
        // Individual blog post pages are generated by mdBlogsPlugin at build time.
        // To add a new post, just drop a .md file in blogs/posts/ and rebuild.
      },
    },
  },
});
